class Solution:
    def findMirror(self, root, target):
        def traverse(node, level, path):
            if not node:
                return None
            if node.data == target:
                return path
            left_path = traverse(node.left, level + 1, path + ['L'])
            if left_path:
                return left_path
            right_path = traverse(node.right, level + 1, path + ['R'])
            if right_path:
                return right_path
            return None

        def find_mirror_from_path(node, path):
            if not node or not path:
                return node
            if path[0] == 'L':
                return find_mirror_from_path(node.right, path[1:])
            else:
                return find_mirror_from_path(node.left, path[1:])

        target_path = traverse(root, 0, [])
        if not target_path:
            return -1
        mirror_node = find_mirror_from_path(root, target_path)
        if not mirror_node:
            return -1
        return mirror_node.data
